#include <Arduino.h>
const int sensorPin = 34;
const int ledPin = 2;
void setup() { Serial.begin(115200); pinMode(ledPin, OUTPUT); }
void loop() {
    int reading = analogRead(sensorPin);
    int brightness = map(reading, 0, 4095, 0, 255);
    analogWrite(ledPin, constrain(brightness, 0, 255));
    Serial.println(reading);
    delay(250);
}

